from typing import Protocol
import pandas as pd

class Source(Protocol):
    def read(self, key: str) -> bytes: ...

class Sink(Protocol):
    def write(self, df: pd.DataFrame) -> int: ...

def clean(df: pd.DataFrame) -> pd.DataFrame:      # pure -> easy to test
    return df[df["qty"] > 0].rename(columns=str.lower)

class ReportProcessor:
    def __init__(self, source: Source, sink: Sink, parse=pd.read_csv):
        self.source, self.sink, self.parse = source, sink, parse

    def run(self, key: str) -> int:
        import io
        df = self.parse(io.BytesIO(self.source.read(key)))
        return self.sink.write(clean(df))
